const listRecentRoomMessages = `-- name: ListRecentRoomMessages :many
SELECT id, room_id, sender_type, sender_id, message_type, content, metadata, created_at FROM room_message
WHERE room_id = $1
ORDER BY created_at DESC
LIMIT $2
`

type ListRecentRoomMessagesParams struct {
	RoomID pgtype.UUID `json:"room_id"`
	Limit  int32       `json:"limit"`
}

func (q *Queries) ListRecentRoomMessages(ctx context.Context, arg ListRecentRoomMessagesParams) ([]RoomMessage, error) {
	rows, err := q.db.Query(ctx, listRecentRoomMessages, arg.RoomID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RoomMessage{}
	for rows.Next() {
		var i RoomMessage
		if err := rows.Scan(
			&i.ID,
			&i.RoomID,
			&i.SenderType,
			&i.SenderID,
			&i.MessageType,
			&i.Content,
			&i.Metadata,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

